#!/bin/sh\nset -e\n\n# Read the input message (GitHub actions passes inputs as environment variables prefixed with INPUT_)\nmsg=\"${INPUT_MESSAGE}\"\n\n# Simple keyword‑to‑emoji mapping (case‑insensitive)\ncase "${msg}" in\n  *[Ff][Ii][Xx]*) emoji=\"🐛\";;\n  *[Aa][Dd][Dd]*|*[Ff][Ee][Aa][Tt][Uu][Rr][Ee]*) emoji=\"✨\";;\n  *[Rr][Ee][Mm][Oo][Vv][Ee]*|*[Dd][Ee][Ll][Ee][Tt][Ee]*) emoji=\"🗑️\";;\n  *[Dd][Oo][Cc][Ss]*) emoji=\"📚\";;\n  *) emoji=\"🔧\";;\nesac\n\n# Emit the output using the legacy set-output command\nprintf "::set-output name=enhanced_message::%s %s\n" "$emoji" "$msg"\n
